def test_newest_first_with_cancelled_and_discounted_totals(shop):
    first = place(shop, "c1", ("PEN", 1))
    second = place(shop, "c1", ("LAMP", 2))  # 12000 -> 10% off
    third = place(shop, "c1", ("BOOK", 1))
    place(shop, "c2", ("BOOK", 1))
    shop.orders.handle_cancel(first)
    body = shop.insights.handle_order_history("c1").body
    assert body["customer_id"] == "c1"
    assert body["orders"] == [
        {"order_id": third, "status": "placed", "total_cents": 2_500},
        {"order_id": second, "status": "placed", "total_cents": 10_800},
        {"order_id": first, "status": "cancelled", "total_cents": 300},
    ]
    for entry in body["orders"]:
        assert entry["total_cents"] == shop.orders.handle_get(entry["order_id"]).body["total_cents"]


