def test_top_customers_ranking(shop):
    shop.customers.handle_register({"customer_id": "c0", "name": "Zed", "email": "z@example.com"})
    shop.customers.handle_register({"customer_id": "c3", "name": "Idle", "email": "i@example.com"})
    place(shop, "c1", ("BOOK", 1))
    place(shop, "c0", ("BOOK", 1))  # ties with c1 -> c0 first
    place(shop, "c2", ("LAMP", 2))  # 12000 gold 15% -> 10200
    cancelled = place(shop, "c3", ("LAMP", 1))
    shop.orders.handle_cancel(cancelled)  # c3 has value 0 -> excluded
    response = shop.insights.handle_top_customers(10)
    assert response.status == 200
    assert response.body == {"customers": [
        {"customer_id": "c2", "name": "Grace", "lifetime_value_cents": 10_200},
        {"customer_id": "c0", "name": "Zed", "lifetime_value_cents": 2_500},
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": 2_500},
    ]}
    assert [c["customer_id"] for c in shop.insights.handle_top_customers(2).body["customers"]] == ["c2", "c0"]


